<script>document.addEventListener('DOMContentLoaded',function(){const l=document.getElementById('galleryLightbox'),i=document.getElementById('galleryLightboxImage'),c=document.getElementById('galleryLightboxCaption'),b=document.getElementById('galleryLightboxClose');function close(){l.classList.remove('is-open');i.src='';document.body.style.overflow=''}document.querySelectorAll('.home-gallery-img').forEach(function(x){x.addEventListener('click',function(){i.src=x.dataset.fullImage;i.alt=x.alt||'';c.textContent=x.dataset.caption||'';l.classList.add('is-open');document.body.style.overflow='hidden'})});b.addEventListener('click',close);l.addEventListener('click',e=>{if(e.target===l)close()});document.addEventListener('keydown',e=>{if(e.key==='Escape')close()})});</script>
<script>
document.addEventListener('DOMContentLoaded',function(){
const form=document.getElementById('cnetAiForm'),input=document.getElementById('cnetAiInput'),button=document.getElementById('cnetAiButton'),status=document.getElementById('cnetAiStatus'),error=document.getElementById('cnetAiError'),result=document.getElementById('cnetAiResult'),answer=document.getElementById('cnetAiAnswer'),sourcesWrap=document.getElementById('cnetAiSourcesWrap'),sources=document.getElementById('cnetAiSources'),suggestions=document.getElementById('cnetAiSuggestions');
if(!form)return;
form.addEventListener('submit',async function(event){event.preventDefault();const query=input.value.trim();if(query.length<3)return;button.disabled=true;status.classList.remove('d-none');status.classList.add('d-flex');error.classList.add('d-none');result.classList.add('d-none');sources.innerHTML='';suggestions.innerHTML='';
try{const response=await fetch(@json(route('cnet-ai.search')),{method:'POST',headers:{'Accept':'application/json','X-CSRF-TOKEN':form.querySelector('input[name="_token"]').value,'Content-Type':'application/json'},body:JSON.stringify({query:query})});const data=await response.json();if(!response.ok)throw new Error(data.message||'Search could not be completed.');answer.textContent=data.answer;const list=Array.isArray(data.sources)?data.sources:[];list.forEach(function(item){const link=document.createElement('a');link.className='cnet-ai-source';link.href=item.url;link.target='_blank';link.rel='noopener noreferrer';link.textContent=item.title||'Web source';sources.appendChild(link)});sourcesWrap.classList.toggle('d-none',list.length===0);if(data.search_suggestions)suggestions.innerHTML=data.search_suggestions;result.classList.remove('d-none');result.scrollIntoView({behavior:'smooth',block:'nearest'});}catch(err){error.textContent=err.message;error.classList.remove('d-none');}finally{button.disabled=false;status.classList.add('d-none');status.classList.remove('d-flex');}});
});
</script>
@endsection
